CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.ucf_controls (
  control_id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  code                  TEXT NOT NULL UNIQUE,
  objective_en          TEXT,
  objective_ar          TEXT,
  activity_en           TEXT,
  activity_ar           TEXT,
  owner                 TEXT,
  frequency             TEXT,
  evidence_requirements JSONB NOT NULL DEFAULT '[]',
  test_steps            JSONB NOT NULL DEFAULT '[]',
  exception_rules       JSONB NOT NULL DEFAULT '[]',
  lifecycle_state       TEXT NOT NULL DEFAULT 'draft'
                        CHECK (lifecycle_state IN ('draft','active','deprecated','retired')),
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.crosswalk_mappings (
  mapping_id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  source_control_id     UUID NOT NULL REFERENCES __TENANT_SCHEMA__.ucf_controls(control_id) ON DELETE CASCADE,
  target_requirement_id TEXT NOT NULL,
  relationship          TEXT NOT NULL DEFAULT 'related'
                        CHECK (relationship IN ('equivalent','partial','related','derived_from')),
  confidence            NUMERIC(5,2) NOT NULL DEFAULT 1.0 CHECK (confidence BETWEEN 0 AND 1),
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_crosswalk_source ON __TENANT_SCHEMA__.crosswalk_mappings(source_control_id);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.csa_campaigns (
  campaign_id    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title          TEXT NOT NULL,
  description    TEXT,
  control_ids    JSONB NOT NULL DEFAULT '[]',
  respondent_ids JSONB NOT NULL DEFAULT '[]',
  deadline       DATE,
  status         TEXT NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft','active','closed','archived')),
  created_by     TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.csa_responses (
  response_id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id           UUID NOT NULL REFERENCES __TENANT_SCHEMA__.csa_campaigns(campaign_id) ON DELETE CASCADE,
  control_id            TEXT NOT NULL,
  respondent            TEXT NOT NULL,
  effectiveness_rating  TEXT NOT NULL DEFAULT 'not_assessed'
                        CHECK (effectiveness_rating IN ('effective','partially_effective','ineffective','not_assessed')),
  design_adequate       BOOLEAN,
  operating_effective   BOOLEAN,
  evidence_available    BOOLEAN,
  comments              TEXT,
  submitted_at          TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_csa_responses_campaign ON __TENANT_SCHEMA__.csa_responses(campaign_id);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.control_test_schedules (
  schedule_id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  control_id            TEXT NOT NULL,
  test_type             TEXT,
  frequency             TEXT NOT NULL DEFAULT 'annually'
                        CHECK (frequency IN ('daily','weekly','monthly','quarterly','annually')),
  next_execution_date   DATE,
  last_executed_at      TIMESTAMPTZ,
  last_result           TEXT CHECK (last_result IN ('pass','fail','error') OR last_result IS NULL),
  assigned_to           TEXT,
  auto_execute          BOOLEAN NOT NULL DEFAULT FALSE,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_test_schedules_control ON __TENANT_SCHEMA__.control_test_schedules(control_id);

CREATE INDEX IF NOT EXISTS idx_test_schedules_next ON __TENANT_SCHEMA__.control_test_schedules(next_execution_date);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.control_deficiencies (
  deficiency_id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  control_id            TEXT NOT NULL,
