CREATE INDEX IF NOT EXISTS idx_deficiencies_control ON __TENANT_SCHEMA__.control_deficiencies(control_id);

CREATE INDEX IF NOT EXISTS idx_deficiencies_status ON __TENANT_SCHEMA__.control_deficiencies(status);

CREATE TABLE IF NOT EXISTS __TENANT_SCHEMA__.control_effectiveness_assessments (
  assessment_id      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  control_id         TEXT NOT NULL,
  assessment_type    TEXT NOT NULL DEFAULT 'design'
                     CHECK (assessment_type IN ('design','operating')),
  rating             TEXT NOT NULL DEFAULT 'not_assessed'
                     CHECK (rating IN ('effective','partially_effective','ineffective','not_assessed')),
  evidence_reference TEXT,
