);

CREATE INDEX IF NOT EXISTS idx_effectiveness_control ON __TENANT_SCHEMA__.control_effectiveness_assessments(control_id);

CREATE INDEX IF NOT EXISTS idx_effectiveness_date ON __TENANT_SCHEMA__.control_effectiveness_assessments(assessment_date DESC);

